"""Read CLOSED resources/GC logs; no JVM requests or heap/profile reader."""
from pathlib import Path
import csv,datetime as dt,hashlib,json,re,sys
ROOT=Path(__file__).resolve().parents[1]
BASE=Path('/drive-testcomp/opentaint-go-rules/demand-storage-predefined-20261028')
PROJECTS=('OWASP','conductor','thingsboard','Stirling-PDF')
GC=re.compile(r'GC\((\d+)\) (.*?) (\d+[KMG]?)->(\d+[KMG]?)\((\d+[KMG]?)\)')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def size(v):return int(v[:-1])*{'K':1024,'M':1024**2,'G':1024**3}[v[-1]]if v[-1]in'KMG'else int(v)
def gcrow(line):
 if not re.search(r'\[gc\s*\]',line):return None
 m=GC.search(line)
 if not m:return None
 at=dt.datetime.strptime(line.split(']')[0].lstrip('['),'%Y-%m-%dT%H:%M:%S.%f%z')
 return{'utc':at.isoformat(),'gc_id':int(m[1]),'kind':m[2],'before_bytes_rounded':size(m[3]),'after_bytes_rounded':size(m[4]),'capacity_bytes_rounded':size(m[5])}
def young_or_full(rows):return[r for r in rows if r['kind'].startswith(('Pause Young','Pause Full'))]
def stats(rows,key):
 if not rows:return{'samples':0,'first':None,'last':None,'min':None,'max':None}
 return{'samples':len(rows),'first':rows[0][key],'last':rows[-1][key],'min':min(r[key]for r in rows),'max':max(r[key]for r in rows)}
def clock(line,day):
 m=re.match(r'(\d\d:\d\d:\d\d\.\d+)',line)
 return None if not m else dt.datetime.fromisoformat(str(day)+'T'+m[1]+'+00:00')
def controls():
 assert size('16G')==16*1024**3 and size('17M')==17*1024**2 and size('3K')==3072 and size('13')==13
 a=gcrow('[2026-10-29T08:00:00.125+0000][2.5s][info][gc          ] GC(8) Pause Young (Normal) (G1 Evacuation Pause) 5421M->3894M(6240M) 32.742ms')
 assert a['after_bytes_rounded']==3894*1024**2 and a['gc_id']==8 and a['utc']=='2026-10-29T08:00:00.125000+00:00'
 assert gcrow('[2026-10-29T08:00:00.125+0000][info][gc,heap] GC(8) Eden regions: 12->0(8)')is None
 assert gcrow('[2026-10-29T08:00:00.125+0000][info][gc,metaspace] GC(8) Metaspace: 123K(256K)->124K(256K)')is None
 assert stats([], 'rss')['max']is None
 assert stats([{'rss':2},{'rss':5},{'rss':3}],'rss')=={'samples':3,'first':2,'last':3,'min':2,'max':5}
 assert len(young_or_full([{'kind':'Pause Remark'},{'kind':'Pause Young (Mixed)'},{'kind':'Pause Full (Heap Dump Initiated GC)'}]))==2
 print('PASS7controls',flush=True)
def dataset(root,project,label,out):
 d=root/'projects'/project/'bidi';m=json.loads((d/'manifest.json').read_text());s=json.loads((d/'summary.json').read_text());anchor=dt.datetime.fromisoformat(m['started_utc'].replace('Z','+00:00'));day=anchor.date()
 resources=[json.loads(line)for line in(d/'resources.jsonl').read_text().splitlines()if line.strip()]
 heaps=[]
 with(d/'gc.log').open()as f:
  for line in f:
   row=gcrow(line)
   if row:row['elapsed_approx']=(dt.datetime.fromisoformat(row['utc'])-anchor).total_seconds();heaps.append(row)
 phases=[]
 phasefile=root/'phase-evidence.json';p=next(p for p in json.loads(phasefile.read_text())['projects']if p['project']==project)
 for run in p['iterations']:
  start=clock(run['start_line'],day);end=clock(run['end_line'],day)if'end_line'in run else None
  if end and end<start:end+=dt.timedelta(days=1)
  lo=(start-anchor).total_seconds();hi=(end-anchor).total_seconds()if end else max(r['elapsed']for r in resources)
  rr=[r for r in resources if lo<=r['elapsed']<=hi];gg=[g for g in heaps if lo<=g['elapsed_approx']<=hi]
  phases.append({'run':run['run'],'direction':run['direction'],'field_limit':run['field_limit'],'status':run['status'],'start_elapsed_approx':lo,'end_elapsed_approx':hi,'rss_bytes':stats(rr,'rss'),'GC_after_used_bytes_rounded':stats(gg,'after_bytes_rounded'),'GC_young_or_full_after_used_bytes_rounded':stats(young_or_full(gg),'after_bytes_rounded'),'GC_before_used_bytes_rounded':stats(gg,'before_bytes_rounded'),'GC_committed_capacity_bytes_rounded':stats(gg,'capacity_bytes_rounded')})
 rpath=out/(project+'-'+label+'-rss.csv');gpath=out/(project+'-'+label+'-gc.csv')
 with rpath.open('w')as f:
  w=csv.DictWriter(f,fieldnames=['elapsed','rss','cpu_seconds','mem_available_bytes','swap_used_bytes','load_average_1m'],extrasaction='ignore');w.writeheader();w.writerows(resources)
 with gpath.open('w')as f:
  w=csv.DictWriter(f,fieldnames=['elapsed_approx','utc','gc_id','kind','before_bytes_rounded','after_bytes_rounded','capacity_bytes_rounded']);w.writeheader();w.writerows(heaps)
 return{'project':project,'label':label,'revision':m['revision'],'heap':m['config']['memory'],'status':s['status'],'latest_reached':s['latest_bidi_iteration'],'latest_complete':s['latest_complete_bidi_iteration'],'accepted_forward':s['latest_accepted_forward_report'],'rss_bytes':stats(resources,'rss'),'GC_after_used_bytes_rounded':stats(heaps,'after_bytes_rounded'),'GC_young_or_full_after_used_bytes_rounded':stats(young_or_full(heaps),'after_bytes_rounded'),'phases':phases,'csv':{'rss':str(rpath),'GC':str(gpath)},'inputs':[{ 'path':str(d/n),'sha256':sha(d/n)}for n in('manifest.json','summary.json','resources.jsonl','gc.log')]+[{'path':str(phasefile),'sha256':sha(phasefile)}]}
def main():
 if'--controls'in sys.argv:controls();return
 assert(ROOT/'campaign-terminal.json').is_file(),'Only after allmeasuredanalyzersclose'
 out=ROOT/'memory-trajectory';out.mkdir(exist_ok=False);rows=[]
 for project in PROJECTS:
  for base,label in((BASE,'saved-default'),(ROOT,'heap16g')):rows.append(dataset(base,project,label,out))
 payload={'runtime_revision':json.loads((ROOT/'preparation/campaign-plan.json').read_text())['selected_runtime_commit'],'source_sha256':sha(Path(__file__)),'limits':['RSS includes heap/nonheap and is not retained heap. GC summary after-used includes uncollected garbage and is not owner-retained memory.','GC sizes use rounded logged binary units. Before/after/capacity are distinct; committed capacity is not -Xmx.','resources.elapsed is the saved monotonic campaign clock. Aligning it with rounded-second manifest UTC and log phase clocks has about2s uncertainty; global peakRSS is exact over saved samples.','Samples represent existing logs only. No new runtime polling, manual dumps, JVM calls, MAT or JFR reader occurs.','Saved default Stirling run5 contains a15.489s manual dump; the16g campaign has no manualdump. Automatic captures remain in phase times.'],'datasets':rows}
 (ROOT/'memory-trajectory.json').write_text(json.dumps(payload,indent=2)+'\n');print('READY',ROOT/'memory-trajectory.json',flush=True)
if __name__=='__main__':main()
